	public function statement($user_id)
	{
		$start_date = $this->input->get('start_date');
		$end_date = $this->input->get('end_date');
		// $start_date = date('Y-m-d H:i:s', strtotime($start_datee . ' 12:00:00'));
		// $end_date   = date('Y-m-d H:i:s', strtotime($end_datee . ' +1 day 06:00:00'));

		// 1. Get all transactions
		$data['transactions'] = $this->Tbl_openno_model->get_coin_statement($user_id, $start_date, $end_date);

		// 2. Get ledger name
		$data['party'] = $this->Tbl_openno_model->get_ledger_name($user_id);
		$data['start_date'] = $start_date;
		$data['end_date'] = $end_date;

		// 3. Get final_hisab (P/L) values date-wise
		$pl_query = $this->db
			->select('date, final_hisab')
			->from('tbl_final_hisab')
			->where('ledger_id', $user_id)
			->where('STR_TO_DATE(date, "%d-%m-%Y") >=', date('Y-m-d', strtotime($start_date)))
			->where('STR_TO_DATE(date, "%d-%m-%Y") <=', date('Y-m-d', strtotime($end_date)))
			->get()
			->result_array();
		//pr($pl_query);
		//echo $this->db->last_query(); exit; 
		// 4. Format P/L map
		$pl_map = [];
		foreach ($pl_query as $row) {
			// Convert 25-07-2025 → 2025-07-25
			$formatted = date('Y-m-d', strtotime(str_replace('/', '-', $row['date'])));
			$pl_map[$formatted] = (float) $row['final_hisab'];
		}

		$data['pl_map'] = $pl_map; // Pass to view
		//pr($data);
		// 5. Load view
		$data['_view'] = 'tbl_openno/statement';
		$this->load->view('layouts/main', $data);
	}


