		$openingball = $this->Tbl_openno_model->final_ledger_results_party($date, $_POST['ledger_id']);

		//echo '<pre>'; print_r($openingball); echo '</pre>'; die;

		if (empty($openingball)) {

			$openingbal = $openingballedger[0]['openingbalance'];
		} else {

			$openingbal = $openingball[0]['opening_bal'];
		}

		$backvoucher = $this->Tbl_openno_model->ledger_get_back_voucher($_POST);

		$tpamnt = $this->Tbl_openno_model->ledger_get_tpamnt($_POST);

		$tpamntt = 0;

		foreach ($tpamnt as $key => $val) {

			$tpamntt = $tpamntt + (($val['Net_profit'] * $val['TP_perc']) / 100);
		}

		$vc = 0;

		foreach ($voucher as $key => $val) {

			if ($_POST['ledger_id'] == $val['PartyId']) {

				$vc = $vc - $val['Amount'];
			}

			if ($_POST['ledger_id'] == $val['Collect_By']) {

				$vc = $vc + $val['Amount'];
			}
		}

		$bvc = 0;

		foreach ($backvoucher as $key => $val) {

			if ($_POST['ledger_id'] == $val['PartyId']) {

				$bvc = $bvc - $val['Amount'];
			}

			if ($_POST['ledger_id'] == $val['Collect_By']) {

				$bvc = $bvc + $val['Amount'];
			}
		}

		$data['ob'] = $vc;

		//$data['opening'] = $openingbal;

		$data['opening'] = ($openingbal) ? $openingbal : $openingballedger[0]['openingbalance'];

		$data['today_hisab'] = $openingball[0]['today_hisab'];

		$data['final_hisab'] = $openingball[0]['final_hisab'];

		$data['backvoucher'] = $bvc;

		//echo '<pre>'; print_r($data); echo '</pre>'; die;

		$data['_view'] = 'tbl_openno/view_till_date_ledgers_app';

		$this->load->view('layouts/main_login', $data);
