	function updateopening()
	{
		$limit = 0;
		$update = 0;
		date_default_timezone_set('Asia/Kolkata');

		if (isset($_POST) && !empty($_POST)) {
			$param['todate'] = $_POST['frdate'];
		} else {
			$param['todate'] = date('Y-m-d', (time()));
			$param['fromdate'] = date('Y-m-d', (time()));
		}

		if (isset($_POST) && !empty($_POST)) {
			$prevdate = date('Y-m-d', (strtotime('-1 day', strtotime($param['todate']))));
			$curdate = date('Y-m-d', (strtotime('0 day', strtotime($param['todate']))));
			$currentDay = date('j', (strtotime('0 day', strtotime($param['todate']))));

			if ($currentDay == 1) {
				if ($this->session->userdata['id'] == '1') {
					$prevdayopening = $this->Tbl_openno_model->get_all_opening_by_date_ledger_admin($prevdate, $limit);
				} else {
					$prevdayopening = $this->Tbl_openno_model->get_all_opening_by_date_ledger($prevdate, $limit, $this->session->userdata['id']);
				}
			} else {
				if ($this->session->userdata['id'] == '1') {
					$prevdayopening = $this->Tbl_openno_model->get_all_opening_by_date_admin($prevdate, $limit);
				} else {
					$prevdayopening = $this->Tbl_openno_model->get_all_opening_by_date($prevdate, $limit, $this->session->userdata['id']);
				}
			}

			//echo '<pre>'; print_r($prevdayopening); echo '</pre>'; die;
			// Chunk size for processing
			$chunk_size = 30;
			$total_records = count($prevdayopening);  // Get the total number of records
			$total_chunks = ceil($total_records / $chunk_size);  // Calculate how many chunks are needed

			// Loop through the chunks
			for ($chunk = 0; $chunk < $total_chunks; $chunk++) {
				// Calculate the offset for each chunk
				$offset = $chunk * $chunk_size;
				// Fetch the chunk of records using LIMIT and OFFSET
				$chunked_data = array_slice($prevdayopening, $offset, $chunk_size);

				// Process each record in the current chunk
				foreach ($chunked_data as $key => $val) {
					if (empty($val['opening'])) {
						$val['opening'] = 0;
						//$val['final'] = 0;
					}
					//echo '<pre>'; print_r($val); die;
