	function insertresulttempmay($opennoid, $date, $shift_id, $num)
	{
		if ($num != 100 && $num != '00') {
			$itr = 1;
			//$this->session->userdata['id']
			if ($this->session->userdata['id'] == '1') {
				$allusers = $this->Tbl_openno_model->getallusersofnumbermayadmin($shift_id, $date);
			} else {
				$allusers = $this->Tbl_openno_model->getallusersofnumbermay($shift_id, $date, $this->session->userdata['id']);
			}
			//echo '<pre>';echo $num; print_r($allusers); echo '<pre>'; die;
			foreach ($allusers as $key => $val) {
				$shift_id = $val['ShiftId'];
				$date = $val['Date'];
				$partyid = $val['PartyId'];
				//var_dump($shift_id);
				//$checkparty = $this->checkparty($partyid);
				//print_r($checkparty); die;
				$trns_add = $this->Tbl_openno_model->get_all_trnsnumber($shift_id, $date, $num, $partyid);
				//echo '<pre>';echo $num; print_r($trns_add); echo '<pre>'; die;
				$trnf2[$key]['Open_Number_amount'] = $akmnt = 0;
				foreach ($trns_add as $tkey => $tval) {

					$arr = explode(',', $tval['number']);
					$amt = explode(',', $tval['amount']);
					$numm = sprintf("%02d", $num);
					$a = (string) $numm;
					for ($i = 0; $i < count($arr); $i++) {
						//echo '<pre>'; print_r(($arr[$i])); echo '</pre>'; //die; 
						if (strlen($arr[$i]) == '3') {

							$nu = sprintf("%02d", $arr[$i]);
							$n = (string) $nu;
							//echo '<pre>'; print_r(($a[1]));print_r(($n)); echo '</pre>'; die;
							//$ind2 = in_array($a[1],$n[0]);
							if ($a[1] == $n[0]) {
								//echo ' index '.$i.' bahar '.$a[1].' amnt '.$amt[$i].'<br>';
								$akmnt = $akmnt + $amt[$i];
								//echo '<pre>'; print_r($akmnt); echo '</pre>'; 
							}
						}
						if (strlen($arr[$i]) == '4') {
							$nu1 = sprintf("%02d", $arr[$i]);
							$n1 = (string) $nu1;
							//$ind1 = in_array($a[0],$n1[0]);
							if ($a[0] == $n1[0]) {
								$akmnt = $akmnt + $amt[$i];
								//echo $a[0].' aa '.$amt[$i];
								//echo ' index '.$i.' andar '.$a[0].' amnt '.$amt[$i].'<br>';
								//echo '<pre>'; print_r($akmnt); echo '</pre>'; 
							}
						}
						if ($arr[$i] == $num) {
							$trnf2[$key]['Open_Number_amount'] += $amt[$i];
						}
					}
					//echo '<pre>'; print_r($akmnt); echo '</pre>'; 
					//die;
					//echo '<pre>'; print_r($arr); echo '</pre>'; die;
					$trnf2[$key]['Akhar_Number_amount'] = $akmnt;
					$trnf2[$key]['Total_Number_amount'] = array_sum($amt);
					$trnf2[$key]['Total_Akhar_amount'] = 0;
					$trnf2[$key]['Total_amount'] = $trnf2[$key]['Total_Number_amount'];

					if ($trnf2[$key]['Total_amount']) {
						//echo '<pre>'; print_r($trnf2[$key]); echo '</pre>'; die;
						$Tb_Date_shift_party_entry_id = $this->Tbl_transactions_model->add_Tb_Date_total_akhar_numbertemp($val['id'], $partyid, $date, $trnf2[$key]);
					}
				}
			}
		} else {

			$itr = 1;
			if ($num == '100') {
				$num = '00';
			}
			$allusers = $this->Tbl_openno_model->getallusersofnumbermay($shift_id, $date);
			//echo '<pre>';echo $num; print_r($allusers); echo '<pre>'; die;
			foreach ($allusers as $key => $val) {
				$shift_id = $val['ShiftId'];
				$date = $val['Date'];
				$partyid = $val['PartyId'];
				//var_dump($shift_id);
				$trns_add = $this->Tbl_openno_model->get_all_trnsnumber($shift_id, $date, $num, $partyid);
				//echo '<pre>';echo $num; print_r($trns_add); echo '<pre>'; die;
				$trnf2[$key]['Open_Number_amount'] = $akmnt = 0;
				foreach ($trns_add as $tkey => $tval) {

					$arr = explode(',', $tval['number']);
					$amt = explode(',', $tval['amount']);
					$numm = sprintf("%02d", $num);
					$a = (string) $numm;
					for ($i = 0; $i < count($arr); $i++) {
						//echo '<pre>'; print_r(($arr[$i])); echo '</pre>'; //die; 
						if ($arr[$i] === '000' || $arr[$i] === '0000') { //echo $arr[$i].' ak ';
							$akmnt = $akmnt + (int) $amt[$i];
						}

						if ($arr[$i] === '00' || $arr[$i] === '100') { //echo $arr[$i].' on ';
							$trnf2[$key]['Open_Number_amount'] += $amt[$i];
						}
					}
					//echo '<pre>'; print_r($akmnt); echo '</pre>'; 
					//die;
					//echo '<pre>'; print_r($arr); echo '</pre>'; die;
					$trnf2[$key]['Akhar_Number_amount'] = $akmnt;
					$trnf2[$key]['Total_Number_amount'] = array_sum($amt);
					$trnf2[$key]['Total_Akhar_amount'] = 0;
					$trnf2[$key]['Total_amount'] = $trnf2[$key]['Total_Number_amount'];
					//echo '<pre>'; print_r($trnf2[$key]); echo '</pre>';
					if ($trnf2[$key]['Total_amount']) {
						$Tb_Date_shift_party_entry_id = $this->Tbl_transactions_model->add_Tb_Date_total_akhar_numbertemp($val['id'], $partyid, $date, $trnf2[$key]);
